import Foundation

extension ResidenceGuides {
    static let studentResidence = DirectoryGuide(
        cardSummary: .init(ukrainian: "Вступ, кошти, збір 218 €, робота й продовження", german: "Zulassung, Mittel, 218 € Gebühr, Arbeit und Verlängerung"),
        introduction: .init(ukrainian: "Для навчання понад шість місяців громадянам третіх країн зазвичай потрібна Aufenthaltsbewilligung – Student. Це не те саме, що віза D для коротшого перебування.", german: "Für ein Studium über sechs Monate benötigen Drittstaatsangehörige meist eine Aufenthaltsbewilligung – Student. Sie ist nicht dasselbe wie ein Visum D für kürzere Aufenthalte."),
        sections: [
            .init("admission", "graduationcap", "Яке навчання підходить", "Welche Studien zählen",
                  "Потрібне зарахування на навчання, яке визнає закон: зокрема, звичайне навчання у виші або окремі передбачені види позачергового навчання. Просто мовні курси самі по собі не завжди є підставою. Університетська Zulassung і дозвіл на проживання — різні рішення.",
                  "Erforderlich ist die Zulassung zu einem gesetzlich erfassten Studium: etwa einem ordentlichen Hochschulstudium oder bestimmten außerordentlichen Studien. Reine Sprachkurse allein reichen nicht stets aus. Hochschulzulassung und Aufenthaltstitel sind verschiedene Entscheidungen.", source: studentOeAD),
            .init("papers", "doc.text", "Документи й подання", "Unterlagen und Antrag",
                  "Підготуйте паспорт, фото, рішення про зарахування, кошти, медичне страхування та підтвердження житла щонайменше на три місяці для розрахунку витрат. Для першої заяви OeAD також називає довідку про несудимість із країни проживання. Заяву подають через представництво за кордоном або, якщо дозволено, під час законного перебування в Австрії. Якщо рішення затримується, віза чи безвіз через саму заяву не продовжуються.",
                  "Bereiten Sie Pass, Foto, Zulassung, Mittel, Krankenversicherung und einen Unterkunftsnachweis für mindestens drei Monate zur Kostenberechnung vor. Für den Erstantrag nennt der OeAD auch einen Strafregisterauszug aus dem Wohnsitzstaat. Der Antrag erfolgt über die Auslandsvertretung oder, wenn zulässig, während rechtmäßigen Aufenthalts in Österreich. Verzögert sich die Entscheidung, verlängert der Antrag Visum oder visumfreie Zeit nicht.", source: studentOeAD),
            .init("costs", "eurosign.circle", "Кошти та збір у 2026 році", "Mittel und Gebühr 2026",
